const n=new Set;async function c(e){if(!n.has(e)){try{await chrome.tabs.sendMessage(e,{type:"ping"})}catch{console.log(`[WebMCP] Injecting content script into tab ${e}`);try{await chrome.scripting.executeScript({target:{tabId:e},files:["content-script.js"]})}catch(t){console.warn(`[WebMCP] Injection failed for tab ${e}:`,t);return}}n.add(e)}}chrome.tabs.onUpdated.addListener((e,t)=>{t.status==="loading"&&n.delete(e)});chrome.tabs.onRemoved.addListener(e=>n.delete(e));chrome.action.onClicked.addListener(async e=>{e.id!=null&&(await chrome.sidePanel.open({tabId:e.id}),await c(e.id))});chrome.runtime.onMessage.addListener((e,t)=>{var i;e.type==="toolchange"&&((i=t.tab)==null?void 0:i.id)!=null&&chrome.runtime.sendMessage(e).catch(()=>{})});
